site_config:
# Prepared only; not installed. Certificate must exist and be verified first.
server {
    listen 80;
    server_name eliai.cn www.eliai.cn;
    location ^~ /.well-known/acme-challenge/ {
        root /srv/eli-sites/portfolio/acme;
        default_type text/plain;
        try_files $uri =404;
    }
    location / { return 301 https://www.eliai.cn$request_uri; }
}
server {
    listen 443 ssl;
    server_name eliai.cn;
    ssl_certificate /etc/letsencrypt/live/www.eliai.cn/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/www.eliai.cn/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    return 301 https://www.eliai.cn$request_uri;
}
server {
    listen 443 ssl;
    server_name www.eliai.cn;
    ssl_certificate /etc/letsencrypt/live/www.eliai.cn/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/www.eliai.cn/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    root /srv/eli-sites/portfolio/domain-current;
    index index.html;
    autoindex off;
    add_header X-Content-Type-Options nosniff always;
    location / { try_files $uri $uri/ =404; }
    location ~ /\. { deny all; }
    error_page 404 /404.html;
}
